type Ticket = { id: number; title: string };
function withoutTicket(tickets: readonly Ticket[], id: number): Ticket[] { return tickets.filter(t=>t.id!==id); }
console.log(withoutTicket([{id:1,title:"A"},{id:2,title:"B"}],1).map(t=>t.id));

type Ticket = { id: number; title: string };
function renamed(ticket: Ticket, title: string): Ticket { return {...ticket,title}; }
const original={id:1,title:"API"};
console.log(original.title,renamed(original,"Eksport").title);

type Ticket = { id: number; title: string };
function withTitle(tickets: readonly Ticket[], id: number, title: string): Ticket[] { return tickets.map(t=>t.id===id?{...t,title}:t); }
// Nie używaj [...tickets][0].title = ... jako naprawy: element może być nadal współdzielony.

import type { ReactNode } from "react";
export function LocalList({ tags }: { tags: readonly string[] }) { const rows: ReactNode[]=[]; for(const tag of tags) rows.push(<li key={tag}>{tag}</li>); return <ul>{rows}</ul>; }
// Lokalna mutacja nowego kontenera jest dopuszczalna. Zakładamy unikalne tagi.

