type ImmutableTicket = Readonly<Ticket>;
type TicketList = readonly ImmutableTicket[];
// Readonly<Ticket> blokuje przypisanie do pól przez ten typ, readonly tablicy blokuje mutujące metody kontenera.

type Ticket = { status: "OPEN" | "CLOSED" };
function countOpen(tickets: readonly Ticket[]): number { let total=0; for(const t of tickets) if(t.status==="OPEN") total++; return total; }
console.log(countOpen([{status:"OPEN"},{status:"CLOSED"}]));

