type Ticket = { id: number; title: string };
export function CleanTable({ tickets }: { tickets: readonly Ticket[] }) { const sorted=[...tickets].sort((a,b)=>a.id-b.id); return <table><caption>Wierszy: {sorted.length}</caption><tbody>{sorted.map(t=><tr key={t.id}><td>{t.title}</td></tr>)}</tbody></table>; }
// Dwa rendery tych samych props mają tę samą treść, a kolejność i pola wejściowych ticketów pozostają bez zmian.

